1	package pylock
2	
3	import (
4		"sort"
5	
6		"github.com/BurntSushi/toml"
7		"github.com/samber/lo"
8		"golang.org/x/xerrors"
9	
10		"github.com/aquasecurity/trivy/pkg/dependency"
11		"github.com/aquasecurity/trivy/pkg/dependency/parser/python"
12		ftypes "github.com/aquasecurity/trivy/pkg/fanal/types"
13		xio "github.com/aquasecurity/trivy/pkg/x/io"
14	)
15	
16	type Pylock struct {
17		Packages []Package `toml:"packages"`
18	}
19	
20	type Package struct {
21		Name         string       `toml:"name"`
22		Version      string       `toml:"version"`
23		Dependencies []Dependency `toml:"dependencies"`
24	}
25	
26	type Dependency struct {
27		Name    string `toml:"name"`
28		Version string `toml:"version"`
29	}
30	
31	// Parser parses pylock.toml defined in PEP 751.
32	// https://peps.python.org/pep-0751
33	type Parser struct{}
34	
35	func NewParser() *Parser {
36		return &Parser{}
37	}
38	
39	func (p *Parser) Parse(r xio.ReadSeekerAt) ([]ftypes.Package, []ftypes.Dependency, error) {
40		var lock Pylock
41		if _, err := toml.NewDecoder(r).Decode(&lock); err != nil {
42			return nil, nil, xerrors.Errorf("failed to decode pylock.toml: %w", err)
43		}
44	
45		pkgs := make(map[string]ftypes.Package)
46		deps := make(map[string][]string)
47	
48		for _, pkg := range lock.Packages {
49			normalizedPkgName := python.NormalizePkgName(pkg.Name, true)
50			pkgID := packageID(normalizedPkgName, pkg.Version)
51	
52			pkgs[pkgID] = ftypes.Package{
53				ID:      pkgID,
54				Name:    normalizedPkgName,
55				Version: pkg.Version,
56			}
57	
58			var dependsOn []string
59			for _, dep := range pkg.Dependencies {
60				depName := python.NormalizePkgName(dep.Name, true)
61				depID := packageID(depName, dep.Version)
62				dependsOn = append(dependsOn, depID)
63			}
64			if len(dependsOn) > 0 {
65				sort.Strings(dependsOn)
66				deps[pkgID] = dependsOn
67			}
68		}
69	
70		depSlice := lo.MapToSlice(deps, func(pkgID string, dependsOn []string) ftypes.Dependency {
71			if _, ok := pkgs[pkgID]; !ok {
72				return ftypes.Dependency{}
73			}
74	
75			// Filter out dependencies that are not in the package list
76			var dependsOnIDs []string
77			for _, depID := range dependsOn {
78				if _, ok := pkgs[depID]; ok {
79					dependsOnIDs = append(dependsOnIDs, depID)
80				}
81			}
82	
83			return ftypes.Dependency{
84				ID:        pkgID,
85				DependsOn: dependsOnIDs,
86			}
87		})
88	
89		pkgSlice := lo.Values(pkgs)
90		sort.Sort(ftypes.Packages(pkgSlice))
91		sort.Sort(ftypes.Dependencies(depSlice))
92	
93		return pkgSlice, depSlice, nil
94	}
95	
96	func packageID(name, ver string) string {
97		return dependency.ID(ftypes.PyLock, name, ver)
98	}
