1	package poetry
2	
3	import (
4		"context"
5		"errors"
6		"io"
7		"io/fs"
8		"os"
9		"path/filepath"
10	
11		"github.com/samber/lo"
12		"golang.org/x/xerrors"
13	
14		"github.com/aquasecurity/trivy/pkg/dependency/parser/python/poetry"
15		"github.com/aquasecurity/trivy/pkg/dependency/parser/python/pyproject"
16		"github.com/aquasecurity/trivy/pkg/fanal/analyzer"
17		"github.com/aquasecurity/trivy/pkg/fanal/analyzer/language"
18		"github.com/aquasecurity/trivy/pkg/fanal/types"
19		"github.com/aquasecurity/trivy/pkg/log"
20		"github.com/aquasecurity/trivy/pkg/set"
21		"github.com/aquasecurity/trivy/pkg/utils/fsutils"
22	)
23	
24	func init() {
25		analyzer.RegisterPostAnalyzer(analyzer.TypePoetry, newPoetryAnalyzer)
26	}
27	
28	const version = 1
29	
30	type poetryAnalyzer struct {
31		logger          *log.Logger
32		pyprojectParser *pyproject.Parser
33		lockParser      language.Parser
34	}
35	
36	func newPoetryAnalyzer(_ analyzer.AnalyzerOptions) (analyzer.PostAnalyzer, error) {
37		return &poetryAnalyzer{
38			logger:          log.WithPrefix("poetry"),
39			pyprojectParser: pyproject.NewParser(),
40			lockParser:      poetry.NewParser(),
41		}, nil
42	}
43	
44	func (a poetryAnalyzer) PostAnalyze(ctx context.Context, input analyzer.PostAnalysisInput) (*analyzer.AnalysisResult, error) {
45		var apps []types.Application
46	
47		required := func(path string, _ fs.DirEntry) bool {
48			return filepath.Base(path) == types.PoetryLock || input.FilePatterns.Match(path)
49		}
50	
51		err := fsutils.WalkDir(input.FS, ".", required, func(path string, _ fs.DirEntry, r io.Reader) error {
52			// Parse poetry.lock
53			app, err := a.parsePoetryLock(ctx, path, r)
54			if err != nil {
55				return xerrors.Errorf("parse error: %w", err)
56			} else if app == nil {
57				return nil
58			}
59	
60			// Parse pyproject.toml alongside poetry.lock to identify the direct dependencies
61			if err = a.mergePyProject(input.FS, filepath.Dir(path), app); err != nil {
62				a.logger.Warn("Unable to parse pyproject.toml to identify direct dependencies",
63					log.FilePath(filepath.Join(filepath.Dir(path), types.PyProject)), log.Err(err))
64			}
65			apps = append(apps, *app)
66	
67			return nil
68		})
69		if err != nil {
70			return nil, xerrors.Errorf("poetry walk error: %w", err)
71		}
72	
73		return &analyzer.AnalysisResult{
74			Applications: apps,
75		}, nil
76	}
77	
78	func (a poetryAnalyzer) Required(filePath string, _ os.FileInfo) bool {
79		fileName := filepath.Base(filePath)
80		return fileName == types.PoetryLock || fileName == types.PyProject
81	}
82	
83	func (a poetryAnalyzer) Type() analyzer.Type {
84		return analyzer.TypePoetry
85	}
86	
87	func (a poetryAnalyzer) Version() int {
88		return version
89	}
90	
91	func (a poetryAnalyzer) parsePoetryLock(ctx context.Context, path string, r io.Reader) (*types.Application, error) {
92		return language.Parse(ctx, types.Poetry, path, r, a.lockParser)
93	}
94	
95	func (a poetryAnalyzer) mergePyProject(fsys fs.FS, dir string, app *types.Application) error {
96		// Parse pyproject.toml to identify the direct dependencies
97		path := filepath.Join(dir, types.PyProject)
98		project, err := a.parsePyProject(fsys, path)
99		if errors.Is(err, fs.ErrNotExist) {
100			// Assume all the packages are direct dependencies as it cannot identify them from poetry.lock
101			a.logger.Debug("pyproject.toml not found", log.FilePath(path))
102			return nil
103		} else if err != nil {
104			return xerrors.Errorf("unable to parse %s: %w", path, err)
105		}
106	
107		dirDeps := directDeps(project)
108		prodDeps := prodPackages(app, project.MainDeps())
109	
110		// Identify the direct/transitive/dev dependencies
111		for i, pkg := range app.Packages {
112			app.Packages[i].Dev = !prodDeps.Contains(pkg.ID) || app.Packages[i].Dev
113			if dirDeps.Contains(pkg.Name) {
114				app.Packages[i].Relationship = types.RelationshipDirect
115			} else {
116				app.Packages[i].Indirect = true
117				app.Packages[i].Relationship = types.RelationshipIndirect
118			}
119		}
120		return nil
121	}
122	
123	func directDeps(project pyproject.PyProject) set.Set[string] {
124		deps := project.MainDeps()
125		for _, groupDeps := range project.Tool.Poetry.Groups {
126			deps.Append(groupDeps.Dependencies.Items()...)
127		}
