131	func prodPackages(app *types.Application, prodRootDeps set.Set[string]) set.Set[string] {
132		packages := lo.SliceToMap(app.Packages, func(pkg types.Package) (string, types.Package) {
133			return pkg.ID, pkg
134		})
135	
136		visited := set.New[string]()
137	
138		for _, pkg := range packages {
139			if !prodRootDeps.Contains(pkg.Name) {
140				continue
141			}
142			walkPackageDeps(pkg.ID, packages, visited)
143		}
144	
145		return visited
146	}
