88		d, err := calculateDigest(r)
89		if err != nil {
90			log.Warn("Unable to get checksum", log.FilePath(filePath), log.Err(err))
91		}
92	
93		deps := make(map[string][]string)
94		for _, dep := range depGraph {
95			deps[dep.ID] = dep.DependsOn
96		}
97	
98		for i, pkg := range pkgs {
99			// This file path is populated for virtual file paths within archives, such as nested JAR files.
100			if pkg.FilePath == "" {
101				pkgs[i].FilePath = libFilePath
102			}
103			pkgs[i].DependsOn = deps[pkg.ID]
