13	// ID returns a unique ID for the given library.
14	// The package ID is used to construct the dependency graph.
15	// The separator is different for each language type.
16	func ID(ltype types.LangType, name, version string) string {
17		if version == "" {
18			return name
19		}
20	
21		sep := "@"
22		switch ltype {
23		// cf. https://github.com/dotnet/sdk/blob/529132850841a6bcfce96799262ce688e3851875/documentation/specs/runtime-configuration-file.md#targets-section-depsjson
24		case types.Conan, types.DotNetCore:
25			sep = "/"
26		case types.GoModule, types.GoBinary:
27			// Return a module ID according the Go way.
28			// Format: <module_name>@v<module_version>
29			// e.g. github.com/aquasecurity/go-dep-parser@v0.0.0-20230130190635-5e31092b0621
30			if !strings.HasPrefix(version, "v") {
31				version = "v" + version
32			}
33		case types.Jar, types.Pom, types.Gradle, types.Sbt:
34			sep = ":"
35		}
36		return name + sep + version
37	}
