39	// UID calculates the hash of the package for the unique ID
40	func UID(filePath string, pkg types.Package) string {
41		if pkg.Identifier.UID != "" {
42			return pkg.Identifier.UID
43		}
44		v := map[string]any{
45			"filePath": filePath, // To differentiate the hash of the same package but different file path
46			"pkg":      pkg,
47		}
48		hash, err := hashstructure.Hash(v, hashstructure.FormatV2, &hashstructure.HashOptions{
49			ZeroNil:         true,
50			IgnoreZeroValue: true,
51		})
52		if err != nil {
53			log.Warn("Failed to calculate the package hash", log.String("pkg", pkg.Name), log.Err(err))
54		}
55		return strconv.FormatUint(hash, 16)
56	}
